const memFresh = (name) => { process.env.FAHEEM_MEMORY_DIR = fs.mkdtempSync(path.join(os.tmpdir(), "mem-" + name + "-")); return process.env.FAHEEM_MEMORY_DIR; };
await t("Memory: FAHEEM_MEMORY_DIR se jagah + default settings (on, 300 tokens)", () => { const s = MEM.getSettings(); return must(MEM.memDir() === path.resolve(MEMDIR) && s.enabled === true && s.maxTokens === 300, JSON.stringify(s)); });
await t("Memory: default jagah ~/.faheem-ai/memory (ZIP update se bahar, keys.json jaisi)", () => { const src = rd("lib/memory.js"); return must(/os\.homedir\(\), "\.faheem-ai", "memory"/.test(src) && !/process\.cwd\(\)/.test(src.split("memDir")[1].split("\n")[0])); });
await t("Memory: pehli dafa 3 pasand seed (Roman Urdu, Stitch design, Vestire)", () => { const l = MEM.listMemories(); return must(l.length === 3 && l.every((x) => x.type === "preference") && l.some((x) => /Roman Urdu/.test(x.text)) && l.some((x) => /Stitch/.test(x.text)) && l.some((x) => /Vestire/.test(x.text)), l.map((x) => x.title).join()); });
