let memA;
await t("Memory CRUD: add (lesson) id ke sath", () => { const r = MEM.addMemory({ type: "lesson", title: "Cart button", text: "addToCart function define nahi tha — script mein function banaya to cart chal gaya", project: "vestire-store", tags: "cart, js" }); memA = r.item; return must(r.ok && /^[a-z0-9]{6,}$/.test(r.item.id) && r.item.tags.join() === "cart,js" && r.item.project === "vestire-store"); });
