await t("Memory CRUD: delete, dobara delete = error", () => { const b = MEM.addMemory({ type: "note", text: "temp yaad" }).item; const d1 = MEM.deleteMemory(b.id), d2 = MEM.deleteMemory(b.id); return must(d1.ok && !d2.ok && !MEM.listMemories().some((x) => x.id === b.id)); });
await t("Memory: JSONL file (har line alag JSON) — koi database nahi", () => { const lines = fs.readFileSync(path.join(process.env.FAHEEM_MEMORY_DIR, "memories.jsonl"), "utf8").trim().split("\n"); return must(lines.length >= 1 && lines.every((l) => JSON.parse(l).id)); });
