sec("20. v3.13 Memory retrieval (BM25) + injection cap");
for (const [ti, tx, tg] of [["Flights route", "Emirates Lahore Dubai Johannesburg sasta route", "travel"], ["Hero image", "Pollinations image URL hero banner ke liye", "images"], ["Checkout form", "Checkout form validation aur success message zaroori", "form"], ["Footer", "Footer mein WhatsApp link aur address", "footer"]]) MEM.addMemory({ type: "note", title: ti, text: tx, tags: [tg] });
