await t("BM25: 'flight johannesburg' → Flights route pehle", () => { const r = MEM.searchMemories("flight johannesburg route"); return must(r[0]?.title === "Flights route", r.map((x) => x.title).join()); });
await t("BM25: Roman Urdu sawal 'jawab roman urdu' → zubaan wali pasand", () => { const r = MEM.searchMemories("jawab roman urdu mein"); return must(r[0]?.title === "Zubaan", r.map((x) => x.title).join()); });
await t("BM25: score tarteeb neeche ko (desc) + koi match nahi = []", () => { const r = MEM.searchMemories("checkout form validation footer"); const desc = r.every((x, i) => i === 0 || r[i - 1]._score >= x._score); return must(desc && r.length >= 2 && MEM.searchMemories("qqqzzz").length === 0 && MEM.searchMemories("").length === 0); });
await t("BM25: project wali yaad ko boost", () => { MEM.addMemory({ type: "note", project: "shop-b", title: "Banner", text: "banner sale red" }); MEM.addMemory({ type: "note", project: "shop-a", title: "Banner A", text: "banner sale red tag" }); const r = MEM.searchMemories("banner sale", { project: "shop-a" }); return must(r[0]?.project === "shop-a", r.map((x) => x.project).join()); });
for (const cap of [50, 120, 300]) await t(`Injection cap: ${cap} tokens se zyada nahi`, () => { for (let i = 0; i < 15; i++) MEM.addMemory({ type: "note", title: "Cart tip " + i + " " + cap, text: `cart button tip number ${i} ` + "lamba text ".repeat(40), tags: ["cart"] }); const c = MEM.memoryContext("cart button", { maxTokens: cap }); return must(c && MEM.estimateTokens(c) <= cap, `${MEM.estimateTokens(c)} > ${cap}`) && `${MEM.estimateTokens(c)}/${cap}`; });
await t("Injection: sab se mutalliq yaad pehli line par", () => { const c = MEM.memoryContext("addToCart function localStorage", { maxTokens: 300 }); const first = c.split("\n")[1] || ""; return must(/Cart button/.test(first), first); });
await t("Injection: memory band = khali (prompt mein kuch nahi)", () => { MEM.setSettings({ enabled: false }); const c = MEM.memoryContext("cart"); MEM.setSettings({ enabled: true }); return must(c === "" && MEM.memoryContext("cart") !== ""); });
await t("Settings: maxTokens had (50-1500), ghalat value rad", () => { MEM.setSettings({ maxTokens: 10 }); const a = MEM.getSettings().maxTokens; MEM.setSettings({ maxTokens: 99999 }); const b = MEM.getSettings().maxTokens; MEM.setSettings({ maxTokens: 500 }); const c = MEM.getSettings().maxTokens; MEM.setSettings({ maxTokens: 300 }); return must(a === 300 && b === 300 && c === 500); });
sec("21. v3.13 Auto-save: seekh + project khulasa + export/import");
memFresh("auto"); MEM.clearMemories();
await t("Lesson tracker: fail → pass = seekh save", () => { const tr = MEM.lessonTracker("shop"); tr.fail(["index.html: getElementById(\"cart\") — yeh id page par nahi."]); const r = tr.pass("id add ki"); const l = MEM.listMemories({ type: "lesson" }); return must(r?.ok && l.length === 1 && /getElementById/.test(l[0].text) && /id add ki/.test(l[0].text) && l[0].source === "auto"); });
await t("Lesson tracker: bina fail ke pass = kuch save nahi", () => { const tr = MEM.lessonTracker("shop"); const r = tr.pass("x"); return must(r === null && MEM.listMemories({ type: "lesson" }).length === 1); });
await t("Lesson: wohi ghalti dobara = nayi yaad nahi (dedupe)", () => { MEM.saveLesson({ project: "shop", error: "index.html: getElementById(\"cart\") — yeh id page par nahi." }); return must(MEM.listMemories({ type: "lesson" }).length === 1); });
await t("Lesson: autoLessons band = skip", () => { MEM.setSettings({ autoLessons: false }); const r = MEM.saveLesson({ error: "naya masla 123" }); MEM.setSettings({ autoLessons: true }); return must(r.skipped && MEM.listMemories({ type: "lesson" }).length === 1); });
await t("Project khulasa: har project ka ek (update, naya nahi)", () => { MEM.saveProjectSummary({ project: "vestire-store", task: "store banao", summary: "Home + Cart bana", files: ["index.html"] }); MEM.saveProjectSummary({ project: "vestire-store", task: "checkout jodo", summary: "Checkout bana", files: ["checkout.html"] }); const l = MEM.listMemories({ type: "project" }); return must(l.length === 1 && /Checkout bana/.test(l[0].text) && /checkout\.html/.test(l[0].text)); });
let EXP;
await t("Export: JSON (app, version, items, settings)", () => { EXP = MEM.exportMemories(); return must(EXP.app === "faheem-ai-dashboard" && EXP.kind === "memory" && EXP.items.length === 2 && EXP.settings.maxTokens); });
await t("Import (merge) naye folder mein: sab aa gayi, dobara import = sab skip", () => { memFresh("imp"); MEM.clearMemories(); const a = MEM.importMemories(JSON.parse(JSON.stringify(EXP))); const b = MEM.importMemories(EXP); return must(a.ok && a.added === 2 && b.added === 0 && b.skipped === 2 && MEM.listMemories().length === 2, JSON.stringify([a, b])); });
await t("Import (replace) + ghalat file rad", () => { const r = MEM.importMemories({ items: [{ type: "note", text: "sirf yeh" }] }, { mode: "replace" }); const bad = MEM.importMemories({ foo: 1 }); return must(r.ok && MEM.listMemories().length === 1 && !bad.ok); });
await t("Memory injection jori gayi: chat + Agent Mode + Team prompts", () => must(/memoryContext\(lastUser\)/.test(rd("app/api/chat/route.js")) && /memoryContext\(task, \{ project: path\.basename\(dir\) \}\)/.test(rd("lib/agent/loop.js")) && /memoryContext\(q, \{ project: board\.project, maxTokens: 250 \}\)/.test(rd("lib/agent/team.js"))));
await t("Auto-save jora: Agent Mode (finish/test) + website pipeline (fail→pass)", () => must(/tracker\.fail\(problems\)/.test(rd("lib/agent/loop.js")) && /saveProjectSummary\(\{ project: path\.basename\(dir\)/.test(rd("lib/agent/loop.js")) && /lessonTracker\("chat-website"\)/.test(rd("app/api/chat/route.js"))));

sec("22. v3.13 Agent Team (mock brains)");
memFresh("team"); MEM.clearMemories(); MEM.addMemory({ type: "preference", title: "Zubaan", text: "Jawab Roman Urdu mein", pinned: true });
const TM = await import(path.join(ROOT, "lib/agent/team.js"));
const GOOD_HTML = '<!DOCTYPE html><html><head><title>Shop</title><link rel="stylesheet" href="style.css"></head><body><h1>Rang Shop</h1><button onclick="addCart()">Add</button><script>function addCart(){document.body.dataset.c=1}</script></body></html>';
const CSS = ":root{--ink:#1b1b1b}body{color:var(--ink);font-family:system-ui}";
const W = (p, c) => `THOUGHT: likh raha hoon\n<action tool="write_file" path="${p}">\n${c}\n</action>`;
function mockTeam({ designer = () => "Sections: hero, products\nFILES: index.html, style.css", coder, reviewer = () => '{"ok":true,"summary":"Store ban gaya, index.html kholein"}' } = {}) {
  const calls = []; let coderN = 0;
  const ask = async (role, messages) => { calls.push({ role, messages }); const fn = role === "designer" ? designer : role === "coder" ? () => coder(++coderN, messages) : reviewer; const text = await fn(messages); return { text, brain: "mock-" + role, brainId: "mock-" + role }; };
  return { ask, calls };
}
const teamDir = () => fs.mkdtempSync(path.join(os.tmpdir(), "team-"));
const runT = async (m, extra = {}) => { const dir = teamDir(); const ev = []; await TM.runTeam({ project: "t", task: extra.task || "Rang Shop ka store website banao", emit: (e) => ev.push(e), signal: extra.signal, options: extra.options || {}, deps: { dir, ask: m.ask, fallback: extra.fallback, runtimeTest: extra.runtimeTest } }); let board = null; try { board = JSON.parse(fs.readFileSync(path.join(dir, "team.json"), "utf8")); } catch {} return { dir, ev, board }; };
await t("Team: sirf bare kaam (store/website haan, chhota fix nahi)", () => must(TM.isTeamTask("Vestire ka poora online store banao") && TM.isTeamTask("landing page with 3 sections") && !TM.isTeamTask("is function ka typo theek karo")));
await t("Team: 4 roles Designer → Coder → Tester → Reviewer + defaults (3 rounds, 60k, 10 calls)", () => must(TM.ROLES.map((r) => r.id).join() === "designer,coder,tester,reviewer" && TM.DEFAULTS.maxRounds === 3 && TM.DEFAULTS.maxTokens === 60000 && TM.DEFAULTS.maxCalls === 10));
await t("Team: Coder ke actions parse (write + edit + kati hui file)", () => { const a = TM.parseTeamActions(W("index.html", "<p>x</p>") + '\n<action tool="edit_file" path="a.css"><old>a</old><new>b</new></action>'); const c = TM.parseTeamActions('<action tool="write_file" path="b.html">\n<html>'); return must(a.actions.length === 2 && a.actions[0].body.trim() === "<p>x</p>" && a.actions[1].args.old === "a" && !a.cut && c.cut); });
const MP = [{ id: "groq", name: "Groq" }, { id: "gemini", name: "Gemini" }, { id: "zai", name: "Z.ai" }];
await t("Team brains: har role alag free brain (specialist prefer order)", async () => { const ask = TM.makeAsker({ providers: MP, call: async (p) => "ok " + p.id, agents: [{ id: "web", prefer: ["gemini", "groq"] }, { id: "coder", prefer: ["groq", "gemini"] }, { id: "research", prefer: ["zai"] }] }); const a = await ask("designer", []), b = await ask("coder", []), c = await ask("reviewer", []); return must(a.brainId === "gemini" && b.brainId === "groq" && c.brainId === "zai", [a.brainId, b.brainId, c.brainId].join()) && `${a.brainId}/${b.brainId}/${c.brainId}`; });
await t("Team brains: limit wala brain chhor kar agla; sab fail = BrainsError", async () => { const ask = TM.makeAsker({ providers: MP, call: async (p) => { if (p.id !== "zai") throw new Error("limit reached (retry in 60s)"); return "zai ok"; } }); const r = await ask("coder", []); const ask2 = TM.makeAsker({ providers: MP, call: async () => { throw new Error("HTTP 429"); } }); let code = ""; try { await ask2("coder", []); } catch (e) { code = e.code; } return must(r.brainId === "zai" && code === "BRAINS"); });
await t("Team brains: cooling brain skip", async () => { const used = []; const ask = TM.makeAsker({ providers: MP, call: async (p) => { used.push(p.id); return "ok"; }, isCooling: (id) => id === "groq" }); await ask("coder", []); return must(used[0] !== "groq" && !used.includes("groq")); });
let HAPPY;
