sec("23. v3.14 Status light + key masking + key pool");
await t("Status 200 = green", () => must(BS.statusFromHttp(200).light === "green"));
await t("Status 401 = red + expire (Nayi key)", () => { const s = BS.statusFromHttp(401, '{"error":"API key expired"}'); return must(s.light === "red" && s.expired && s.dead, JSON.stringify(s)); });
await t("Status 403 = red (revoke/qubool nahi)", () => { const s = BS.statusFromHttp(403, "forbidden"); return must(s.light === "red" && s.code === 403); });
await t("Status 429 + Retry-After 120 = yellow '2 min baad wapas'", () => { const s = BS.statusFromHttp(429, "", 120); return must(s.light === "yellow" && s.minutes === 2 && /2 min baad wapas/.test(s.label), JSON.stringify(s)); });
await t("Status 429 daily quota (bina header) = yellow 60 min", () => { const s = BS.statusFromHttp(429, "requests per day exceeded"); return must(s.light === "yellow" && s.minutes === 60, JSON.stringify(s)); });
await t("Status 402 = red 'Quota bilkul khatam'", () => { const s = BS.statusFromHttp(402, "payment required"); return must(s.light === "red" && /Quota bilkul khatam/.test(s.label)); });
await t("429 insufficient_quota = red (quota fully dead)", () => must(BS.statusFromHttp(429, '{"error":{"code":"insufficient_quota"}}').light === "red"));
await t("429 Gemini 'check plan and billing' = yellow (red nahi)", () => must(BS.statusFromHttp(429, "You exceeded your current quota, please check your plan and billing details. Please retry in 37s").light === "yellow"));
await t("429 'retry in 37s' message se 1 min", () => must(BS.statusFromHttp(429, "Please retry in 37s").minutes === 1));
await t("Raabta nahi (0) = red", () => must(BS.statusFromHttp(0).light === "red"));
await t("combineLights: koi ek green = green; khali = grey", () => must(BS.combineLights([{ light: "red" }, { light: "yellow" }, { light: "green" }]).light === "green" && BS.combineLights([]).light === "grey"));
await t("maskKey: sirf aakhri 4 (••••WXYZ)", () => { const m = BS.maskKey("gsk_abcdefgh12345678WXYZ"); return must(m === "••••WXYZ" && !m.includes("gsk_") && !m.includes("abcd"), m); });
await t("maskKey khali = khali", () => must(BS.maskKey("") === "" && BS.maskKey(null) === ""));
await t("parsePool: comma/line, duplicate hataye", () => { const p = BS.parsePool("aaaa1111bbbb2222,cccc3333dddd4444\n eeee5555ffff6666 , aaaa1111bbbb2222"); return must(p.length === 3, p.length); });
await t("parsePool: zyada se zyada 5 keys", () => must(BS.parsePool(Array.from({ length: 9 }, (_, i) => "key" + i + "x".repeat(12)).join(",")).length === 5));
await t("poolPick: band (401) aur aaram (429) wali keys chhorta hai", () => { const st = BS.createPoolState(); BS.poolMark("g", "k1", 401, 60, st); BS.poolMark("g", "k2", 429, 60, st); return must(BS.poolPick("g", ["k1", "k2", "k3"], [], st) === "k3"); });
await t("poolMark 429: aaram ke baad key wapas", () => { const st = BS.createPoolState(); const now = 1e12; BS.poolMark("g", "k1", 429, 30, st, now); return must(BS.poolPick("g", ["k1"], [], st, now + 1000) === null && BS.poolPick("g", ["k1"], [], st, now + 31000) === "k1"); });
await t("poolMark 401: key hamesha ke liye band; 200 se wapas", () => { const st = BS.createPoolState(); BS.poolMark("g", "k1", 401, 60, st); const a = BS.poolPick("g", ["k1"], [], st); BS.poolMark("g", "k1", 200, 0, st); return must(a === null && BS.poolPick("g", ["k1"], [], st) === "k1"); });
await t("Pool: GROQ_API_KEY 'k1,k2' = 2 keys, pehli istemal", () => { const p = prov({ GROQ_API_KEY: "gsk_one" + "a".repeat(20) + ",gsk_two" + "b".repeat(20) }, "groq"); return must(p.pool.length === 2 && p.key.startsWith("gsk_one")); });
await t("Pool rotation: 429 par agli key se jawab (cooldown nahi)", async () => { const k1 = "gsk_rot1" + "a".repeat(20), k2 = "gsk_rot2" + "b".repeat(20); routes = [[/groq/, (u, b, o) => o.headers.Authorization === "Bearer " + k1 ? J(429, {}, { "retry-after": "40" }) : OK("doosri key ne jawab diya")]]; calls.length = 0; const r = await P.callProvider(prov({ GROQ_API_KEY: `${k1},${k2}` }, "groq"), msgs); return must(r === "doosri key ne jawab diya" && calls.at(-1).headers.Authorization === "Bearer " + k2 && !P.isCooling("groq"), r); });
await t("Pool: 429 wali key aaram par, agli dafa doosri key pehle", () => { const p = prov({ GROQ_API_KEY: "gsk_rot1" + "a".repeat(20) + ",gsk_rot2" + "b".repeat(20) }, "groq"); return must(p.key.startsWith("gsk_rot2"), p.key.slice(0, 8)); });
await t("Pool: 401 par key band, doosri se jawab", async () => { const k1 = "zai_dead" + "a".repeat(24), k2 = "zai_live" + "b".repeat(24); routes = [[/api\.z\.ai/, (u, b, o) => o.headers.Authorization === "Bearer " + k1 ? J(401, { error: "invalid key" }) : OK("live key")]]; const r = await P.callProvider(prov({ ZAI_API_KEY: `${k1},${k2}` }, "zai"), msgs); const p2 = prov({ ZAI_API_KEY: `${k1},${k2}` }, "zai"); return must(r === "live key" && p2.key === k2); });
await t("Pool: sab keys 429 = saaf 'limit reached'", async () => { routes = [[/mistral/, () => J(429, {}, { "retry-after": "20" })]]; try { await P.callProvider(prov({ MISTRAL_API_KEY: "mis_a" + "a".repeat(20) + ",mis_b" + "b".repeat(20) }, "mistral"), msgs); return false; } catch (e) { return must(/limit reached/.test(e.message), e.message); } });
await t("Ek key: pool nahi (purana raasta waisa hi)", () => must(prov({ COHERE_API_KEY: "c".repeat(30) }, "cohere").pool === undefined));
await t("codeFromError: HTTP 401 / limit reached / fetch failed", () => must(BS.codeFromError("HTTP 401: x") === 401 && BS.codeFromError("limit reached (retry in 30s)") === 429 && BS.codeFromError("fetch failed") === 0));
await t("Lal light madad: 'Nayi key banayein — No expiration chunein' + link", () => { const h = BS.expiryHelp("https://console.groq.com/keys"); return must(/No expiration chunein/.test(h.text) && h.url.startsWith("https://")); });
await t("Brains API poori key kabhi nahi lautata (maskKey har jagah)", () => { const s = rd("app/api/brains/route.js"); return must(/keys\.map\(maskKey\)/.test(s) && !/keys:\s*keys[,\s}]/.test(s) && /parsePool\(next\)\.map\(maskKey\)/.test(s)); });
await t("Status check sasta: /models ya max_tokens 1", () => { const s = rd("lib/brain-check.js"); return must(/max_tokens: 1/.test(s) && /\/models/.test(s) && /CHECK_EVERY_MS = 30 \* 60 \* 1000/.test(s)); });

sec("24. v3.14 Rooms + attach routing + pagination + thinking dots");
await t("Room id: ../ aur ajeeb naam rad", () => must(RM.safeRoomId("../keys") === null && RM.safeRoomId("a/b") === null && RM.safeRoomId("groq") === "groq"));
await t("Room history save + parhna (~/.faheem-ai/rooms/<id>.json)", () => { RM.appendRoom("groq", [{ role: "user", content: "salam" }, { role: "assistant", content: "wsalam", ms: 900 }]); const r = RM.readRoom("groq"); return must(r.messages.length === 2 && fs.existsSync(path.join(process.env.FAHEEM_ROOMS_DIR, "groq.json"))); });
await t("Rooms alag alag (groq ki history gemini mein nahi)", () => { RM.appendRoom("gemini", [{ role: "user", content: "g" }]); return must(RM.readRoom("gemini").messages.length === 1 && RM.readRoom("groq").messages.length === 2); });
await t("Picture ka data history file mein nahi (sirf naam)", () => { RM.appendRoom("freeai", [{ role: "user", content: "dekho", files: ["a.png"], dataUrl: "data:image/png;base64,AAAA" }]); const raw = fs.readFileSync(path.join(process.env.FAHEEM_ROOMS_DIR, "freeai.json"), "utf8"); return must(!raw.includes("data:image") && raw.includes("a.png")); });
await t("History had: aakhri 200 messages", () => { RM.appendRoom("cap", Array.from({ length: 210 }, (_, i) => ({ role: "user", content: "m" + i }))); const r = RM.readRoom("cap"); return must(r.messages.length === 200 && r.messages[0].content === "m10"); });
await t("historyFor: error/note nahi, aakhri 12", () => { RM.appendRoom("hf", [...Array.from({ length: 20 }, (_, i) => ({ role: i % 2 ? "assistant" : "user", content: "x" + i })), { role: "note", content: "n" }, { role: "assistant", content: "bad", err: true }]); const h = RM.historyFor(RM.readRoom("hf")); return must(h.length === 12 && !h.some((m) => m.content === "bad" || m.content === "n")); });
await t("Room clear: history mit gayi", () => { RM.clearRoom("cap"); return must(RM.readRoom("cap").messages.length === 0); });
const IMG = "data:image/png;base64," + PNG1.toString("base64");
await t("Attach: vision brain ko picture image_url mein", () => { const r = BS.routeAttachments({ name: "Gemini", vision: true }, "kya hai?", [{ kind: "image", name: "a.png", dataUrl: IMG }]); return must(Array.isArray(r.content) && r.content[1].type === "image_url" && r.imageCount === 1 && !r.notes.length); });
await t("Attach: bina-vision brain = picture nahi jati + saaf note", () => { const r = BS.routeAttachments({ name: "Mistral", vision: false }, "kya hai?", [{ kind: "image", name: "a.png", dataUrl: IMG }]); return must(typeof r.content === "string" && r.imageCount === 0 && /tasveer nahi dekh sakta/.test(r.notes[0])); });
await t("Attach: text file parh kar message mein", () => { const r = BS.routeAttachments({ vision: false }, "summary", [{ kind: "text", name: "notes.md", text: "Vestire black gold" }]); return must(/\[File: notes\.md\]/.test(r.content) && /Vestire black gold/.test(r.content)); });
await t("Attach: video sirf maloomat + note", () => { const r = BS.routeAttachments({ vision: true }, "dekho", [{ kind: "video", name: "v.mp4", duration: 12.4 }]); return must(/Video lagi: v\.mp4, 12s/.test(r.text) && r.notes.length === 1); });
await t("Attach routing: Groq vision model / Free.ai qwen25-vl rooms API mein", () => { const s = rd("app/api/rooms/route.js"); return must(/p\.visionModel \|\| p\.roomVisionModel/.test(s) && /routeAttachments/.test(s)); });
const ROOMS22 = [...CAT.CATALOG.map((c) => ({ id: c.id })), { id: "ollama" }, { id: "puter" }];
await t("Pagination: 22 rooms = 6 pages, har page par 4 tak", () => { const v = BS.pageRooms(ROOMS22, 1); return must(v.pages === 6 && v.items.length === 4 && v.total === 22, JSON.stringify({ p: v.pages, n: v.items.length })); });
await t("Page 1 sab se tez: Groq, Gemini, Z.ai, Mistral", () => must(BS.pageRooms(ROOMS22, 1).items.map((r) => r.id).join() === "groq,gemini,zai,mistral"));
await t("Aakhri page ke siwa har page par bilkul 4", () => { for (let p = 1; p < 6; p++) must(BS.pageRooms(ROOMS22, p).items.length === 4, "page " + p); return must(BS.pageRooms(ROOMS22, 6).items.length === 2); });
await t("Pagination: ghalat page number clamp", () => must(BS.pageRooms(ROOMS22, 99).page === 6 && BS.pageRooms(ROOMS22, -3).page === 1));
await t("Har room ek hi dafa (koi duplicate nahi)", () => { const all = []; for (let p = 1; p <= 6; p++) all.push(...BS.pageRooms(ROOMS22, p).items.map((r) => r.id)); return must(all.length === 22 && new Set(all).size === 22); });
await t("Thinking dots: start → active, stop → band", () => { const s = TH.createThinkingStore(); const seen = []; s.subscribe((n) => seen.push(n)); s.start("groq"); const on = s.count(); s.stop("groq"); return must(on === 1 && s.count() === 0 && seen.join() === "1,0"); });
await t("Thinking dots: do brains — ek ruka, doosra chal raha", () => { const s = TH.createThinkingStore(); s.start("a"); s.start("b"); s.stop("a"); return must(s.count() === 1 && s.isActive("b") && !s.isActive("a")); });
await t("Thinking: kaun si calls (POST chat/tools/rooms send/agent)", () => must(TH.isThinkingRequest("/api/chat", "POST") && TH.isThinkingRequest("http://localhost:3000/api/tools", "POST") && TH.isThinkingRequest("/api/rooms", "POST", '{"action":"send","id":"groq"}') && !TH.isThinkingRequest("/api/rooms", "POST", '{"action":"append"}') && !TH.isThinkingRequest("/api/chat", "GET") && !TH.isThinkingRequest("/api/brains", "POST") && TH.isThinkingRequest("/api/agent/team", "POST")));
await t("Reduced-motion: dots ki animation band", () => { const c = rd("app/globals.css"); return must(/prefers-reduced-motion: reduce\)\s*\{\s*\.thinkbar\.on \{ animation: none; \}\s*\.room \.thinkborder rect \{ animation: none; \}/.test(c)); });
await t("Top bar dots har page par (layout mein ThinkingBar)", () => must(/<ThinkingBar \/>/.test(rd("app/layout.js"))));
await t("Room border: laal dots (#ff3b3b) SVG", () => { const c = rd("app/globals.css"); return must(/\.room \.thinkborder rect \{[^}]*stroke: #ff3b3b/.test(c) && /className="thinkborder"/.test(rd("app/brains/page.js"))); });

sec("25. v3.14 Plan B: bina-jhanjhat free brains (mock + live)");
await t("Pollinations purana host: seedha POST text.pollinations.ai/openai, model openai-fast, koi Authorization nahi", async () => { routes = [[/text\.pollinations\.ai/, () => OK("poll ok")]]; calls.length = 0; globalThis.__cfg = {}; const p = P.getProviders().find((x) => x.id === "pollfree"); const r = await P.callProvider(p, msgs); const c = calls[0]; return must(r === "poll ok" && c.url === "https://text.pollinations.ai/openai" && c.body.model === "openai-fast" && !c.headers.Authorization, JSON.stringify(c.headers)); });
