await t("Free.ai: api.free.ai/v1/chat/completions, qwen3-coder, bina key", async () => { routes = [[/api\.free\.ai/, () => OK("free ok")]]; calls.length = 0; globalThis.__cfg = {}; const r = await P.callProvider(P.getProviders().find((x) => x.id === "freeai"), msgs); return must(r === "free ok" && calls[0].url === "https://api.free.ai/v1/chat/completions" && calls[0].body.model === "qwen3-coder" && !calls[0].headers.Authorization); });
await t("Free.ai 429: qwen7b par chala jata hai", async () => { routes = [[/api\.free\.ai/, (u, b) => b.model === "qwen3-coder" ? J(429, {}) : OK("qwen7b")]]; globalThis.__cfg = {}; const r = await P.callProvider(P.getProviders().find((x) => x.id === "freeai"), msgs); return must(r === "qwen7b"); });
await t("AI Horde: Bearer 0000000000 (public anonymous) + lambi timeout + aakhri sahara", async () => { routes = [[/aihorde\.net\/v1\/models/, () => J(200, { data: [{ id: "aphrodite/Behemoth-128B" }, { id: "koboldcpp/gemma-4-E4B-it" }] })], [/aihorde\.net/, () => OK("horde ok")]]; calls.length = 0; globalThis.__cfg = {}; const p = P.getProviders().find((x) => x.id === "aihorde"); const r = await P.callProvider(p, msgs); const chat = calls.find((c) => /chat\/completions/.test(c.url)); return must(r === "horde ok" && chat.headers.Authorization === "Bearer 0000000000" && p.minTimeoutMs === 180000 && p.lastResort, JSON.stringify(chat?.headers)); });
await t("AI Horde 'auto' model: instruct model chuna (pick)", () => must(calls.find((c) => /chat\/completions/.test(c.url)).body.model === "koboldcpp/gemma-4-E4B-it"));
await t("Tarteeb: bina-key → live → AI Horde → Ollama", () => { LV.setLiveForTest([{ id: "live-x-m", name: "x", base: "https://example.org/v1", model: "m", keyless: true, live: true }]); globalThis.__cfg = {}; const ids = P.sortProviders(P.getProviders()).map((p) => p.id); LV.setLiveForTest([]); return must(ids.indexOf("freeai") < ids.indexOf("live-x-m") && ids.indexOf("live-x-m") < ids.indexOf("aihorde") && ids.at(-1) === "ollama", ids.join()); });
await t("Chat route bhi AI Horde ko aakhir mein rakhta hai", () => { const s = rd("app/api/chat/route.js"); return must(/pp\?\.lastResort\) return 89/.test(s) && /pp\?\.live\) return 80/.test(s)); });
await t("Mana kiye gaye nahi: OpenCode Zen, Hack Club AI, gpt4free", () => { const ids = CAT.CATALOG.map((c) => c.id + c.base).join(" "); return must(!/opencode|hackclub|hack-club|g4f|gpt4free/i.test(ids) && LV.LIVE_DENY.test("opencode-zen") && LV.LIVE_DENY.test("hack-club-ai") && LV.LIVE_DENY.test("gpt4free")); });
globalThis.fetch = realFetch;
await t("LIVE: Pollinations purana host (bina key) asli jawab", async () => { globalThis.__cfg = {}; const p = P.getProviders().find((x) => x.id === "pollfree"); try { const r = await P.callProvider(p, [{ role: "user", content: "Reply with exactly: OK" }], 40000); return must(r.length > 0) && "jawab: " + r.slice(0, 30).replace(/\s+/g, " "); } catch (e) { throw new Error("free limit/busy: " + e.message.slice(0, 100)); } });
await t("LIVE: Free.ai (bina key) asli jawab", async () => { globalThis.__cfg = {}; const p = P.getProviders().find((x) => x.id === "freeai"); try { const r = await P.callProvider(p, [{ role: "user", content: "Reply with exactly: OK" }], 40000); return must(r.length > 0) && "jawab: " + r.slice(0, 30).replace(/\s+/g, " "); } catch (e) { throw new Error("free limit/busy: " + e.message.slice(0, 100)); } });
await t("LIVE: AI Horde ek koshish (volunteer GPUs, dheema)", async () => { globalThis.__cfg = {}; const p = P.getProviders().find((x) => x.id === "aihorde"); const t0 = Date.now(); try { const r = await P.callProvider(p, [{ role: "user", content: "Reply with exactly: OK" }], 170000); return must(r.length > 0) && `${((Date.now() - t0) / 1000).toFixed(0)}s: ${r.slice(0, 30).replace(/\s+/g, " ")}`; } catch (e) { throw new Error(`${((Date.now() - t0) / 1000).toFixed(0)}s — horde busy/queue: ` + e.message.slice(0, 100)); } });

sec("26. v3.14 Live auto list (stillworks /api/llm/up)");
const UPJ = { count: 6, models: [
  { endpoint: "pollinations", base_url: "https://text.pollinations.ai", chat_path: "/openai", auth: "none", model: "openai-fast", openai_compatible: true, chat_capable: true, openai_base_url: "https://text.pollinations.ai/openai" },
  { endpoint: "free-ai", auth: "none", model: "qwen3-coder", openai_compatible: true, chat_capable: true, openai_base_url: "https://api.free.ai/v1" },
  { endpoint: "kilo-gateway", auth: "none", model: "nvidia/nemotron-3.5-lightning:free", openai_compatible: true, chat_capable: true, openai_base_url: "https://api.kilo.ai/api/gateway" },
  { endpoint: "ovh-anonymous", auth: "none", model: "Qwen3Guard-Gen-8B", openai_compatible: true, chat_capable: true, openai_base_url: "https://oai.endpoints.kepler.ai.cloud.ovh.net/v1" },
  { endpoint: "groq", auth: "bearer", model: "llama", openai_compatible: true, chat_capable: true, openai_base_url: "https://api.groq.com/openai/v1" },
  { endpoint: "opencode-zen", auth: "none", model: "big-pickle", openai_compatible: true, chat_capable: true, openai_base_url: "https://opencode.ai/zen/v1" },
  { endpoint: "llm7", auth_mode: "none", model: "codestral-latest", openai_compatible: true, chat_capable: true, base_url: "https://api.llm7.io", chat_path: "/v1/chat/completions" },
] };
const LP = LV.parseLive(UPJ);
await t("Parse: sirf bina-key (auth none) OpenAI-jaise", () => must(!LP.some((b) => /groq/.test(b.base)) && LP.every((b) => b.keyless && b.live), LP.map((b) => b.id).join()));
await t("Parse: guard/safety models nahi", () => must(!LP.some((b) => /Guard/.test(b.model))));
await t("Parse: OpenCode Zen (ToS) kabhi nahi", () => must(!LP.some((b) => /opencode/.test(b.base))));
await t("Parse: base_url + chat_path se base banta hai (llm7)", () => must(LP.some((b) => b.base === "https://api.llm7.io/v1" && b.model === "codestral-latest")));
await t("Parse: Pollinations /openai = seedha POST (direct)", () => must(LP.find((b) => /pollinations/.test(b.base)).direct === true));
await t("Parse: zyada se zyada 10, ids unique", () => { const big = { models: Array.from({ length: 30 }, (_, i) => ({ endpoint: "e" + i, auth: "none", model: "m" + i, openai_base_url: "https://e" + i + ".example/v1" })) }; const r = LV.parseLive(big); return must(r.length === 10 && new Set(r.map((b) => b.id)).size === 10); });
await t("Catalog wale duplicate hat jate hain (Pollinations/Free.ai)", () => { const d = LV.dedupeLive(LP, CAT.CATALOG); return must(!d.some((b) => b.model === "openai-fast" || b.model === "qwen3-coder") && d.some((b) => /nemotron/.test(b.model)), d.map((b) => b.model).join()); });
await t("Ghalat/khali JSON se crash nahi", () => must(LV.parseLive(null).length === 0 && LV.parseLive({ models: "x" }).length === 0 && LV.parseLive({ models: [null, 5, {}] }).length === 0));
await t("Fail-safe: service band (HTTP 503) = purani list rehti hai", async () => { LV.setLiveForTest([{ id: "live-old", base: "https://o.example/v1", model: "o", live: true, keyless: true }], 1); const r = await LV.refreshLive({ fetchImpl: async () => new Response("down", { status: 503 }) }); return must(!r.ok && r.kept === 1 && LV.liveBrains()[0].id === "live-old", JSON.stringify(r)); });
await t("Fail-safe: network error se crash nahi", async () => { const r = await LV.refreshLive({ fetchImpl: async () => { throw new TypeError("fetch failed"); } }); return must(!r.ok && LV.liveBrains().length === 1); });
await t("Taaza list: parse + cache file (live-brains.json)", async () => { const r = await LV.refreshLive({ fetchImpl: async () => J(200, UPJ) }); return must(r.ok && r.count === LP.length && fs.existsSync(path.join(process.env.FAHEEM_LIVE_DIR, "live-brains.json"))); });
await t("Live brains pipeline mein Ollama se pehle", () => { globalThis.__cfg = {}; const ids = P.sortProviders(P.getProviders()).map((p) => p.id); const i = ids.findIndex((x) => x.startsWith("live-")); return must(i > 0 && i < ids.indexOf("ollama"), ids.join()); });
await t("Options: LIVE_FREE_ENABLED=false = live brains band", () => { globalThis.__cfg = { LIVE_FREE_ENABLED: "false" }; return must(!P.getProviders().some((p) => p.live)); });
await t("FREE_ENABLED=false = live brains bhi band", () => { globalThis.__cfg = { FREE_ENABLED: "false" }; return must(!P.getProviders().some((p) => p.live)); });
await t("Live brain call: koi Authorization nahi", async () => { globalThis.fetch = mockFetch; routes = [[/kilo\.ai/, () => OK("live ok")]]; calls.length = 0; globalThis.__cfg = {}; const p = P.getProviders().find((x) => x.live && /kilo/.test(x.base)); const r = await P.callProvider(p, msgs); globalThis.fetch = realFetch; return must(r === "live ok" && !calls[0].headers.Authorization && calls[0].body.model === "nvidia/nemotron-3.5-lightning:free"); });
LV.setLiveForTest([]);
await t("Options page mein Live list toggle", () => must(/data-live-option/.test(rd("app/components/Settings.js")) && /LIVE_FREE_ENABLED/.test(rd("lib/catalog.js"))));
await t("LIVE: stillworks /api/llm/up asli list parse", async () => { const r = await realFetch(LV.LIVE_URL, { signal: AbortSignal.timeout(15000) }); const j = await r.json(); const b = LV.dedupeLive(LV.parseLive(j), CAT.CATALOG); return must(r.ok && Array.isArray(j.models) && LV.parseLive(j).length > 0) && `${j.models.length} rows → ${b.length} naye temporary brains: ${b.slice(0, 3).map((x) => x.model).join(", ")}`; });

