// Asli browser (playwright-core): naye pages bina JavaScript error ke render hon.
let PWB = null, PWERR = "";
try { const pw = await import("playwright-core"); const tries = process.env.FAHEEM_CHROME ? [{ executablePath: process.env.FAHEEM_CHROME }] : [{ channel: "msedge" }, { channel: "chrome" }, {}]; for (const o of tries) { try { PWB = await pw.chromium.launch({ headless: true, args: ["--no-sandbox", "--disable-gpu"], timeout: 30000, ...o }); break; } catch (e) { PWERR = String(e.message).split("\n")[0].slice(0, 120); } } } catch (e) { PWERR = e.message; }
const pageErrors = async (u, act) => {
  must(PWB, "Browser nahi mila: " + PWERR);
  const pg = await PWB.newPage({ viewport: { width: 1366, height: 820 } }); const errs = [];
  pg.on("pageerror", (e) => errs.push(String(e).slice(0, 160))); pg.on("console", (m) => { if (m.type() === "error" && !/favicon|Failed to load resource/i.test(m.text())) errs.push("console: " + m.text().slice(0, 160)); });
  try { const r = await pg.goto(base + u, { waitUntil: "networkidle", timeout: 45000 }); await pg.waitForTimeout(800); const extra = act ? await act(pg) : ""; must(r.status() === 200, "HTTP " + r.status()); must(!errs.length, errs.join(" | ")); return extra || "0 JS errors"; } finally { await pg.close(); }
};
for (const u of ["/memory", "/agent", "/options", "/skills", "/skills/memory", "/skills/agent-team"]) await t(`Browser: ${u} bina JS error render`, () => pageErrors(u));
await t("Browser: /memory form se yaad add → list mein dikhi", () => pageErrors("/memory", async (pg) => { await pg.fill('[data-memory-form] textarea', "Browser test yaad: Vestire font Playfair"); await pg.click('[data-memory-form] button[type=submit]'); await pg.waitForTimeout(900); const n = await pg.locator("text=Browser test yaad").count(); must(n >= 1, "yaad list mein nahi"); return `item dikh gaya (${n})`; }));
await t("Browser: /agent Team toggle on → Options mein bhi on (prefs)", () => pageErrors("/agent", async (pg) => { await pg.check("[data-team-toggle]"); const v = await pg.evaluate(() => JSON.parse(localStorage.getItem("faheem-ai-prefs") || "{}").teamMode); await pg.goto(base + "/options", { waitUntil: "networkidle" }); await pg.waitForTimeout(500); const on = await pg.isChecked("[data-team-option]"); must(v === true && on, `${v} ${on}`); return "Team mode prefs mein save"; }));
// ---- v3.14 Brains Rooms + Meta + Guide (live server + asli browser) ----
sec("28. v3.14 Live server + asli browser (Brains Rooms, Meta, Guide)");
const BACKUP_F = path.join(ROOT, "data", "keys.backup.json"); const hadBackup = fs.existsSync(BACKUP_F); const oldBackup = hadBackup ? fs.readFileSync(BACKUP_F) : null;
for (const pg of ["/brains", "/meta", "/skills/guide"]) await t(`Page ${pg} khulta hai (200)`, async () => { const r = await get(pg); return must(r.status === 200, String(r.status)); });
await t("/skills/guide: 16 guide cards (server HTML)", async () => { const h = await (await get("/skills/guide")).text(); const n = SK_IDS.filter((i) => h.includes(`data-guide="${i}"`)).length; return must(n === 16 && /Kya karti hai/.test(h) && /Misaal prompt/.test(h), String(n)); });
let BR;
await t("/api/brains GET: 22 rooms (20 catalog + Ollama + Puter)", async () => { BR = await (await get("/api/brains")).json(); return must(BR.ok && BR.rooms.length === 22 && BR.rooms.at(-1).id === "puter" && BR.checkEveryMin === 30, String(BR.rooms?.length)); });
await t("/api/brains: har card par Key lein link (keyUrl https)", () => must(BR.rooms.filter((r) => r.id !== "ollama").every((r) => /^https:\/\//.test(r.keyUrl))));
const FAKE = "sk-faheemtest-" + "q".repeat(24) + "WXYZ";
let SV;
await t("Key Save (Mistral): jawab mein sirf ••••WXYZ, poori key nahi", async () => { const r = await postJ("/api/brains", { action: "save", id: "mistral", keys: FAKE }); const txt = await r.text(); SV = JSON.parse(txt); return must(SV.ok && SV.keys[0] === "••••WXYZ" && !txt.includes("faheemtest"), txt.slice(0, 160)); });
await t("Save par live check: nakli key = red (401) + 'No expiration' madad", () => must(SV.status.light === "red" && SV.status.code === 401 && /No expiration/.test(SV.status.help?.text || ""), JSON.stringify(SV.status)) && SV.status.label);
await t("Key keys.json mein save (isi laptop, test HOME)", () => { const k = JSON.parse(fs.readFileSync(path.join(tmp, ".faheem-ai", "keys.json"), "utf8")); return must(k.MISTRAL_API_KEY === FAKE); });
await t("+ button: doosri key pool mein (2 keys, dono masked)", async () => { const d = await (await postJ("/api/brains", { action: "save", id: "mistral", keys: "sk-second-" + "r".repeat(20) + "ABCD", mode: "add" })).json(); return must(d.ok && d.keys.length === 2 && d.keys[1] === "••••ABCD" && d.status.keys.length === 2); });
await t("/api/brains GET bhi poori key nahi dikhata", async () => { const txt = await (await get("/api/brains")).text(); return must(!txt.includes("faheemtest") && !txt.includes("sk-second") && txt.includes("••••WXYZ")); });
await t("Key hatana (removeKey) + khali/chhoti key = 400", async () => { const a = await (await postJ("/api/brains", { action: "removeKey", id: "mistral", index: 1 })).json(); const b = await postJ("/api/brains", { action: "save", id: "mistral", keys: "short" }); const c = await postJ("/api/brains", { action: "save", id: "pollfree", keys: FAKE }); await postJ("/api/brains", { action: "removeKey", id: "mistral", index: 0 }); return must(a.ok && a.keys.length === 1 && b.status === 400 && c.status === 400); });
await t("/api/brains check: bina-key Pollinations purana = live light", async () => { const d = await (await postJ("/api/brains", { action: "check", id: "pollfree" })).json(); return must(d.ok && ["green", "yellow", "red"].includes(d.status.light)) && `${d.status.light}: ${d.status.label}`; });
await t("/api/brains check: Ollama band = red (saaf wajah)", async () => { const d = await (await postJ("/api/brains", { action: "check", id: "ollama" })).json(); return must(d.status.light === "red" && /Ollama/.test(d.status.label)); });
await t("/api/brains: ghalat brain 404, ghalat JSON 400", async () => { const a = await postJ("/api/brains", { action: "check", id: "nahi" }); const b = await realFetch(base + "/api/brains", { method: "POST", headers: { "content-type": "application/json" }, body: "{bad" }); return must(a.status === 404 && b.status === 400); });
await t("/api/rooms: ghalat id 400, bina key brain 404 (Key lagayein)", async () => { const a = await get("/api/rooms?id=../x"); const b = await postJ("/api/rooms", { action: "send", id: "groq", message: "hi" }); const j = await b.json(); return must(a.status === 400 && b.status === 404 && /key lagayein/i.test(j.error)); });
await t("/api/rooms send: picture bina-vision brain ko nahi jati (note)", async () => { const d = await (await postJ("/api/rooms", { action: "send", id: "pollfree", message: "Reply with exactly: OK", attachments: [{ kind: "image", name: "p.png", dataUrl: "data:image/png;base64," + PNG1.toString("base64") }] })).json(); return must(d.notes?.length === 1 && /tasveer nahi dekh sakta/.test(d.notes[0]), JSON.stringify(d).slice(0, 160)) && (d.ok ? "jawab bhi aaya: " + String(d.text).slice(0, 20) : "note sahi; jawab: " + String(d.error).slice(0, 50)); });
await t("/api/rooms: history file test HOME mein (~/.faheem-ai/rooms/pollfree.json)", async () => { const d = await (await get("/api/rooms?id=pollfree")).json(); return must(d.ok && d.messages.length >= 2 && fs.existsSync(path.join(tmp, ".faheem-ai", "rooms", "pollfree.json"))); });
await t("/api/rooms LIVE: Free.ai room asli jawab", async () => { const d = await (await postJ("/api/rooms", { action: "send", id: "freeai", message: "Reply with exactly: OK" })).json(); return must(d.ok, d.error) && `${(d.ms / 1000).toFixed(1)}s: ${String(d.text).slice(0, 30)}`; });
await t("/api/rooms append (Puter) + clear", async () => { const a = await (await postJ("/api/rooms", { action: "append", id: "puter", messages: [{ role: "user", content: "x" }, { role: "assistant", content: "y" }] })).json(); const c = await (await postJ("/api/rooms", { action: "clear", id: "puter" })).json(); const g = await (await get("/api/rooms?id=puter")).json(); return must(a.ok && a.messages.length === 2 && c.ok && g.messages.length === 0); });
await t("/api/meta GET: paid key nahi, $0.01, muse-image-1.0", async () => { const d = await (await get("/api/meta")).json(); return must(d.ok && d.keySet === false && d.price === 0.01 && d.model === "muse-image-1.0"); });
await t("/api/meta edit: key/switch/confirm ke baghair = 400 (paise nahi lagte)", async () => { const a = await postJ("/api/meta", { action: "edit", image: "data:image/png;base64,AAAA", prompt: "x" }); const b = await postJ("/api/meta", { action: "edit", image: "data:image/png;base64,AAAA", prompt: "x", paidOn: true }); return must(a.status === 400 && b.status === 400); });
await t("/api/meta open: Windows nahi to browser window fallback", async () => { const d = await (await postJ("/api/meta", { action: "open" })).json(); return must(process.platform === "win32" ? d.ok : d.fallback === true && d.url === "https://www.meta.ai"); });
await t("Bahar se (non-localhost) /api/brains, /api/rooms, /api/meta = 403", async () => { const http = await import("http"); const one = (p) => new Promise((res) => { const q = http.request({ host: "127.0.0.1", port: PORT, path: p, headers: { Host: "evil.example.com" } }, (r) => { r.resume(); res(r.statusCode); }); q.on("error", () => res(0)); q.end(); }); const c = [await one("/api/brains"), await one("/api/rooms?id=groq"), await one("/api/meta")]; return must(c.every((x) => x === 403), c.join()); });
try { if (hadBackup) fs.writeFileSync(BACKUP_F, oldBackup); else fs.rmSync(BACKUP_F, { force: true }); } catch {}
for (const u of ["/brains", "/meta", "/skills/guide"]) await t(`Browser: ${u} bina JS error render`, () => pageErrors(u));
await t("Browser: /brains Page 1 = 4 rooms (Groq, Gemini, Z.ai, Mistral) 2x2", () => pageErrors("/brains", async (pg) => { await pg.waitForSelector("[data-room]"); const ids = await pg.$$eval("[data-room]", (els) => els.map((e) => e.dataset.room)); const cols = await pg.$eval("[data-roomgrid]", (e) => getComputedStyle(e).gridTemplateColumns.split(" ").length); must(ids.join() === "groq,gemini,zai,mistral" && cols === 2, ids.join() + " cols " + cols); return "4 rooms, 2 columns"; }));
await t("Browser: Page tabs 1..6, har page par 4 (aakhri 2)", () => pageErrors("/brains", async (pg) => { await pg.waitForSelector("[data-page-tab]"); const n = await pg.$$eval("[data-page-tab]", (e) => e.length); const counts = []; for (let i = 1; i <= n; i++) { await pg.click(`[data-page-tab="${i}"]`); await pg.waitForTimeout(150); counts.push(await pg.$$eval("[data-room]", (e) => e.length)); } must(n === 6 && counts.slice(0, 5).every((c) => c === 4) && counts[5] === 2, n + " " + counts.join()); return counts.join(","); }));
await t("Browser: thinking dots — kaam par chalu, jawab par band (room border + top bar)", () => pageErrors("/brains", async (pg) => {
  await pg.route("**/api/rooms", async (route) => { if (route.request().method() !== "POST") return route.continue(); await new Promise((r) => setTimeout(r, 1500)); await route.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify({ ok: true, text: "mock jawab", notes: [], ms: 1500, model: "x" }) }); });
  await pg.waitForSelector('[data-room="groq"] form input[type=text]');
  const before = await pg.getAttribute("[data-thinking-bar]", "data-active");
  await pg.fill('[data-room="groq"] form input[type=text]', "salam"); await pg.click('[data-room="groq"] form button[type=submit]');
  await pg.waitForTimeout(500);
  const during = await pg.getAttribute("[data-thinking-bar]", "data-active"); const roomOn = await pg.$eval('[data-room="groq"]', (e) => e.classList.contains("thinking"));
  await pg.waitForSelector("text=mock jawab", { timeout: 5000 }); await pg.waitForTimeout(300);
  const after = await pg.getAttribute("[data-thinking-bar]", "data-active"); const roomOff = await pg.$eval('[data-room="groq"]', (e) => !e.classList.contains("thinking"));
  must(before === "0" && during === "1" && roomOn && after === "0" && roomOff, [before, during, roomOn, after, roomOff].join()); return "0 → 1 (dots) → 0";
}));
await t("Browser: reduced-motion par dots ki animation band", async () => { must(PWB, "browser nahi"); const ctx = await PWB.newContext({ reducedMotion: "reduce" }); const pg = await ctx.newPage(); try { await pg.goto(base + "/brains", { waitUntil: "networkidle" }); const a = await pg.evaluate(() => { const b = document.querySelector("[data-thinking-bar]"); b.classList.add("on"); return getComputedStyle(b).animationName; }); must(a === "none", a); return "animation: none"; } finally { await ctx.close(); } });
await t("Browser: key input password type + Save ke baad masked chip", () => pageErrors("/brains", async (pg) => {
  await pg.route("**/api/brains", async (route) => { const rq = route.request(); if (rq.method() === "POST" && /"save"/.test(rq.postData() || "")) return route.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify({ ok: true, keys: ["••••9Z9Z"], status: { light: "green", label: "Chal rahi hai" } }) }); return route.continue(); });
  await pg.waitForSelector('[data-room="gemini"]'); await pg.click('[data-room="gemini"] button[aria-label="Key aur status"]');
  const type = await pg.getAttribute('[data-room="gemini"] [data-key-input]', "type");
  await pg.fill('[data-room="gemini"] [data-key-input]', "AIzaFAKE-browser-test-key-9Z9Z"); await pg.click('[data-room="gemini"] [data-key-save]'); await pg.waitForTimeout(400);
  const chip = await pg.textContent('[data-room="gemini"] [data-masked-key]'); const light = await pg.getAttribute('[data-room="gemini"]', "data-light"); const html = await pg.content();
  must(type === "password" && /••••9Z9Z/.test(chip) && light === "green" && !html.includes("AIzaFAKE-browser"), [type, chip, light].join()); return "masked + green";
}));
await t("Browser: /meta paid switch default OFF, Paid button band", () => pageErrors("/meta", async (pg) => { await pg.waitForSelector("[data-paid-toggle]"); const on = await pg.isChecked("[data-paid-toggle]"); const dis = await pg.isDisabled("[data-paid-run]"); const warn = await pg.textContent("[data-paid-warning]"); must(!on && dis && /\$0\.01 har tasveer/.test(warn), [on, dis, warn].join()); return "OFF + disabled + warning"; }));
await t("Browser: /meta 5 templates + 'Meta AI mein kholo' button", () => pageErrors("/meta", async (pg) => { const n = await pg.$$eval("[data-template]", (e) => e.length); const b = await pg.textContent("[data-open-meta]"); must(n === 5 && /Meta AI mein kholo/.test(b)); return n + " templates"; }));
await t("Browser: /skills/guide 16 cards + /skills par Guide link", () => pageErrors("/skills", async (pg) => { const has = await pg.$("[data-guide-link]"); await pg.goto(base + "/skills/guide", { waitUntil: "networkidle" }); const n = await pg.$$eval("[data-guide]", (e) => e.length); must(has && n === 16, String(n)); return n + " cards"; }));

try { await PWB?.close(); } catch {}
try { process.kill(-srv.pid); } catch {}

sec("11. Build + Browser Tester");
await t("Next.js build pass", () => { const o = execSync("npx next build 2>&1", { cwd: ROOT, encoding: "utf8", timeout: 300000 }); return must(/Compiled successfully/.test(o)); });
await t("Browser Tester: achha page pass", () => { fs.writeFileSync(path.join(tmp, "good.html"), '<html><body><button onclick="document.body.dataset.x=1">Buy</button></body></html>'); const d = JSON.parse(execSync(`node scripts/runtime-test.cjs ${tmp}/good.html`, { cwd: ROOT, encoding: "utf8", timeout: 40000 })); return must(d.ok && d.clicked === 1) && `clicked ${d.clicked}/${d.buttons}`; });
await t("Browser Tester: toota button pakarta hai", () => { fs.writeFileSync(path.join(tmp, "bad.html"), '<html><body><button onclick="addToCart()">Buy</button></body></html>'); let o; try { o = execSync(`node scripts/runtime-test.cjs ${tmp}/bad.html`, { cwd: ROOT, encoding: "utf8", timeout: 40000 }); } catch (e) { o = e.stdout; } const d = JSON.parse(o); return must(!d.ok && d.errors.length > 0) && d.errors[0].slice(0, 70); });

fs.mkdirSync(path.join(ROOT, "data"), { recursive: true }); fs.writeFileSync(path.join(ROOT, "data", "test-results.json"), JSON.stringify(R, null, 1));
const pass = R.filter((r) => r.ok).length;
console.log(`TOTAL ${R.length} PASS ${pass} FAIL ${R.length - pass}`);
for (const r of R.filter((r) => !r.ok)) console.log("FAIL", r.sec, "|", r.name, "|", r.note);
process.exit(0);
